{
  "name": "ASI MS2000显微镜控制器",
  "name_en": "ASI MS2000 Microscope Controller",
  "manufacturer": "Applied Scientific Instrumentation (ASI)",
  "description": "用于显微镜自动化的多轴控制器，可驱动X、Y、Z载物台或调焦轴，并在部分配置下控制LED照明通道。常用于显微成像中的样品定位、扫描、对焦以及光源联动控制。",
  "description_en": "A multi-axis controller for microscope automation that can drive X, Y, and Z stage or focus axes, and on some configurations also control LED illumination channels. It is commonly used for sample positioning, scanning, focusing, and coordinated light control in microscopy experiments.",
  "tag_hints": [
    "microscope stage controller",
    "multi-axis motion control",
    "XY/Z stage positioning",
    "automated microscopy",
    "LED illumination control",
    "sample scanning"
  ],
  "actions": [
    {
      "action_name": "auto-is_busy",
      "description": "查询控制器是否忙碌。",
      "description_en": "Check whether the controller is busy."
    },
    {
      "action_name": "auto-get_number_axes",
      "description": "获取控制器支持的运动轴数量。",
      "description_en": "Get the number of motion axes supported by the controller."
    },
    {
      "action_name": "auto-get_number_leds",
      "description": "获取控制器可控制的LED通道数量。",
      "description_en": "Get the number of LED channels controllable by the controller."
    },
    {
      "action_name": "auto-command",
      "description": "向控制器发送原始命令。",
      "description_en": "Send a raw command to the controller."
    },
    {
      "action_name": "auto-readline",
      "description": "读取控制器返回的一行响应。",
      "description_en": "Read a single line of response from the controller."
    },
    {
      "action_name": "auto-read_multiline",
      "description": "读取控制器返回的多行响应。",
      "description_en": "Read a multiline response from the controller."
    },
    {
      "action_name": "auto-read_until_timeout",
      "description": "持续读取控制器响应直到通信超时。",
      "description_en": "Read controller responses until communication times out."
    },
    {
      "action_name": "auto-wait_until_idle",
      "description": "等待控制器完成当前运动或操作并进入空闲状态。",
      "description_en": "Wait until the controller finishes the current operation and becomes idle."
    },
    {
      "action_name": "auto-get_command",
      "description": "发送查询命令并获取控制器返回值。",
      "description_en": "Send a query command and get the returned value from the controller."
    },
    {
      "action_name": "auto-set_command",
      "description": "发送设置命令以更改控制器参数。",
      "description_en": "Send a set command to change a controller parameter."
    },
    {
      "action_name": "auto-get_description",
      "description": "获取指定命令或功能的描述信息。",
      "description_en": "Get description information for a command or feature."
    },
    {
      "action_name": "auto-changed_timeout",
      "description": "设置与控制器通信的超时时间。",
      "description_en": "Set the communication timeout used with the controller."
    },
    {
      "action_name": "auto-move_command",
      "description": "向受控运动轴发送运动命令。",
      "description_en": "Send a motion command to a controlled axis."
    },
    {
      "action_name": "auto-move_by_relative_position",
      "description": "按相对位移移动指定轴。",
      "description_en": "Move the specified axis by a relative distance."
    },
    {
      "action_name": "auto-move_to_absolute_position",
      "description": "将指定轴移动到绝对位置。",
      "description_en": "Move the specified axis to an absolute position."
    },
    {
      "action_name": "auto-move_to_limit",
      "description": "以指定速度将指定轴移动到限位方向。",
      "description_en": "Drive the specified axis toward a limit at the given speed."
    },
    {
      "action_name": "auto-motor_moving",
      "description": "查询指定轴电机是否正在运动。",
      "description_en": "Check whether the specified axis motor is moving."
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置指定轴的运动速度。",
      "description_en": "Set the movement speed of the specified axis."
    },
    {
      "action_name": "auto-find_max_speed",
      "description": "查找并返回指定轴的最大速度。",
      "description_en": "Determine and return the maximum speed of the specified axis."
    },
    {
      "action_name": "auto-wait_for_motor_stop",
      "description": "等待指定轴电机停止。",
      "description_en": "Wait for the specified axis motor to stop."
    },
    {
      "action_name": "auto-reset_position",
      "description": "将指定轴当前位置重置为参考零点。",
      "description_en": "Reset the current position of the specified axis as a reference zero."
    },
    {
      "action_name": "auto-get_absolute_position",
      "description": "获取指定轴的绝对位置。",
      "description_en": "Get the absolute position of the specified axis."
    },
    {
      "action_name": "auto-is_led_on",
      "description": "查询指定LED通道是否开启。",
      "description_en": "Check whether the specified LED channel is on."
    },
    {
      "action_name": "auto-get_led_power",
      "description": "获取指定LED通道的输出功率。",
      "description_en": "Get the output power of the specified LED channel."
    },
    {
      "action_name": "auto-set_led_power",
      "description": "设置指定LED通道的输出功率。",
      "description_en": "Set the output power of the specified LED channel."
    }
  ]
}

